{
  "findings": [
    {
      "check_id": "CKV_AWS_46",
      "title": "Secrets exposed in EC2 user data",
      "resource": "aws_launch_template.web_app",
      "severity": "HIGH",
      "explanation": "The database password and a hard-coded API key are embedded in launch template user data, which can expose them through Terraform state, AWS APIs, and instance metadata."
    },
    {
      "check_id": "CKV_AWS_79",
      "title": "IMDSv2 is not enforced",
      "resource": "aws_launch_template.web_app",
      "severity": "HIGH",
      "explanation": "The launch template does not require IMDSv2, allowing instances to use the less secure IMDSv1 protocol and increasing the risk of credential theft through SSRF."
    }
  ],
  "patched_code": "resource "aws_launch_template" "web_app" {
  name_prefix   = "automated-employee-onboarding-platform-lt-web-"
  image_id      = data.aws_ami.ubuntu.id
  instance_type = var.instance_type
  key_name      = var.key_pair_name
  vpc_security_group_ids = [aws_security_group.web_app.id]
  user_data = base64encode(<<-EOF
              apt-get update
              apt-get install -y nginx nodejs npm
              systemctl start nginx
              systemctl enable nginx
              EOF
  )

  metadata_options {
    http_tokens = "required"
  }

  tag_specifications {
    resource_type = "instance"
  }
}
",
  "fix_summary": "Removed the database password and hard-coded API key from instance user data. Added launch template metadata options requiring IMDSv2."
}
